--
-- Structure for view `v_finished_goods_stock_report`
--
DROP TABLE IF EXISTS `v_finished_goods_stock_report`;

CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_finished_goods_stock_report`  AS SELECT `items`.`id` AS `id`, `items`.`name` AS `name`, `items`.`code` AS `code`, `items`.`unit_weight` AS `unit_weight`, `items`.`sell_price` AS `sell_price`, sum(if(`invoice_detail`.`type` = 'output',`invoice_detail`.`total_quantity`,0)) AS `qty_in`, sum(if(`invoice_detail`.`type` = 'invoice',`invoice_detail`.`total_quantity`,0)) AS `qty_out`, sum(if(`invoice_detail`.`type` = 'output',`invoice_detail`.`total_quantity`,0)) - sum(if(`invoice_detail`.`type` = 'invoice',`invoice_detail`.`total_quantity`,0)) AS `balance`, `items`.`category_id` AS `category_id`, `categories`.`name` AS `category_name`, `items`.`purchase_price` AS `purchase_price` FROM ((`items` left join `invoice_detail` on(`invoice_detail`.`item_id` = `items`.`id`)) join `categories` on(`items`.`category_id` = `categories`.`id`)) WHERE `items`.`type` = 'Good' GROUP BY `items`.`id`, `items`.`name`, `items`.`code`, `items`.`sell_price`, `items`.`purchase_price`, `items`.`unit_weight`, `items`.`category_id`, `categories`.`name` ;

-- --------------------------------------------------------

--
-- Structure for view `v_item_stock_report`
--
DROP TABLE IF EXISTS `v_item_stock_report`;

CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_item_stock_report`  AS SELECT `invoice_detail`.`item_id` AS `item_id`, sum(if(`invoice_detail`.`type` = 'receipt',`invoice_detail`.`net_weight`,0)) AS `qty_in`, sum(if(`invoice_detail`.`type` = 'production',`invoice_detail`.`net_weight`,0)) AS `qty_out`, sum(if(`invoice_detail`.`type` = 'receipt',`invoice_detail`.`net_weight`,0)) - sum(if(`invoice_detail`.`type` = 'production',`invoice_detail`.`net_weight`,0)) AS `balance` FROM `invoice_detail` GROUP BY `invoice_detail`.`item_id` ;

