--
DROP TABLE IF EXISTS `v_raw_material_avg_unit_price`;

CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_raw_material_avg_unit_price`  AS SELECT `items`.`name` AS `name`, `items`.`id` AS `item_id`, `items`.`category_id` AS `category_id`, `categories`.`name` AS `category_name`, ifnull(`v_item_stock_report`.`qty_in`,0) AS `qty_in`, ifnull(`v_item_stock_report`.`qty_out`,0) AS `qty_out`, ifnull(`v_item_stock_report`.`balance`,0) AS `balance`, `units`.`base_unit` AS `base_unit`, `items`.`unit_id` AS `unit_id`, (select `invoice_detail`.`per_unit_price` from `invoice_detail` where `invoice_detail`.`type` = 'receipt' and `invoice_detail`.`item_id` = `items`.`id` order by `invoice_detail`.`date` desc limit 1) AS `purchase_unit_price`, (select sum(`invoice_detail`.`total_price_stock`) / sum(`invoice_detail`.`net_weight`) from `invoice_detail` where `invoice_detail`.`type` = 'receipt' and `invoice_detail`.`item_id` = `items`.`id`) AS `average_unit_price` FROM (((`items` left join `v_item_stock_report` on(`items`.`id` = `v_item_stock_report`.`item_id`)) join `units` on(`units`.`id` = `items`.`unit_id`)) left join `categories` on(`categories`.`id` = `items`.`category_id`)) WHERE `items`.`type` = 'Raw' ;

